import{_ as e,o as n,c as s,a3 as t}from"./chunks/framework.BkJHvlZ8.js";const u=JSON.parse('{"title":"架构与请求链路","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":null}'),p={name:"guide/architecture.md"};function i(d,a,l,c,o,r){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="架构与请求链路" tabindex="-1">架构与请求链路 <a class="header-anchor" href="#架构与请求链路" aria-label="Permalink to &quot;架构与请求链路&quot;">​</a></h1><h2 id="应用启动" tabindex="-1">应用启动 <a class="header-anchor" href="#应用启动" aria-label="Permalink to &quot;应用启动&quot;">​</a></h2><p><code>backend/src/main.py</code> 的 lifespan 按以下顺序启动应用：</p><ol><li>初始化日志、中间件和异常处理器。</li><li>初始化数据库连接；开发环境可以自动建表。</li><li>执行核心种子数据，确保默认部门、角色和菜单存在。</li><li>扫描 <code>backend/src/plugins/builtin</code>，同步插件元数据和启用状态。</li><li>执行启用插件的 <code>install()</code>，再注册 HTTP 路由、MCP 工具和事件监听器。</li><li>注册 MCP HTTP 路由，发送 <code>APP_STARTUP</code> 事件。</li></ol><p>关闭应用时，插件会先卸载运行时资源，再关闭数据库连接池。</p><h2 id="后端分层" tabindex="-1">后端分层 <a class="header-anchor" href="#后端分层" aria-label="Permalink to &quot;后端分层&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP Request</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Middleware（请求 ID、CORS、异常过滤、操作日志）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>FastAPI Router</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Dependency（get_db / get_current_user / require_permission）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>CRUD / Service</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>SQLAlchemy Model + AsyncSession</span></span></code></pre></div><p>路由层负责参数校验和响应格式，业务规则放在服务函数中，数据库提交集中在业务操作的事务边界内。统一成功响应格式为 <code>{ code, msg, data }</code>；业务异常由全局处理器转换为同样的错误结构。</p><h2 id="前端路由" tabindex="-1">前端路由 <a class="header-anchor" href="#前端路由" aria-label="Permalink to &quot;前端路由&quot;">​</a></h2><p>管理台启动时先加载用户信息和菜单树。<code>frontend/src/router/index.ts</code> 使用 <code>import.meta.glob(&#39;@/views/**/*.vue&#39;)</code> 查找菜单的 <code>component</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>菜单 component: apehub_web/admin/Config</span></span>
<span class="line"><span>页面文件:       frontend/src/views/apehub_web/admin/Config.vue</span></span>
<span class="line"><span>访问路径:       /apehub-web/admin/config</span></span></code></pre></div><p>组件不存在时不会生成动态路由，用户会进入 404。因此菜单注册、页面文件和权限标识必须作为一个版本交付。</p><h2 id="apehub-web-的三类接口" tabindex="-1">Apehub_web 的三类接口 <a class="header-anchor" href="#apehub-web-的三类接口" aria-label="Permalink to &quot;Apehub_web 的三类接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>示例</th><th>鉴权</th></tr></thead><tbody><tr><td>官网公开接口</td><td><code>/api/v1/apehub-web/site/public/*</code></td><td>不需要登录</td></tr><tr><td>开发者接口</td><td><code>/api/v1/apehub-web/developer/*</code></td><td>JWT 登录</td></tr><tr><td>后台管理接口</td><td><code>/api/v1/apehub-web/admin/*</code></td><td>JWT + 插件权限</td></tr></tbody></table><p>公开接口只返回已启用、已发布的数据；开发者接口只允许访问自己的插件；后台接口由 <code>apehub_web:*</code> 菜单权限保护。</p>`,15)])])}const b=e(p,[["render",i]]);export{u as __pageData,b as default};
